<?php
require_once dirname(__DIR__).'/includes/admin_helpers.php';exigirAdmin();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_validar();$acao=(string)($_POST['acao']??'');$id=(int)($_POST['id']??0);if($acao==='excluir'&&$id>0){$s=$conexao->prepare('DELETE FROM cursos WHERE id=?');$s->bind_param('i',$id);$s->execute();$s->close();adminLog($conexao,'excluir','curso',$id);}elseif(in_array($acao,['criar','editar'],true)){$titulo=trim((string)($_POST['titulo']??''));$descricao=trim((string)($_POST['descricao']??''));$plataforma=trim((string)($_POST['plataforma']??''));$carga=max(0,(int)($_POST['carga_horaria']??0));$link=trim((string)($_POST['link']??''));$categoria=trim((string)($_POST['categoria']??''));if($titulo!==''&&mb_strlen($titulo)<=180&&($link===''||filter_var($link,FILTER_VALIDATE_URL))){if($acao==='criar'){$s=$conexao->prepare('INSERT INTO cursos(titulo,descricao,plataforma,carga_horaria,link,categoria) VALUES(?,?,?,?,?,?)');$s->bind_param('sssiss',$titulo,$descricao,$plataforma,$carga,$link,$categoria);}else{$s=$conexao->prepare('UPDATE cursos SET titulo=?,descricao=?,plataforma=?,carga_horaria=?,link=?,categoria=? WHERE id=?');$s->bind_param('sssissi',$titulo,$descricao,$plataforma,$carga,$link,$categoria,$id);}if($s->execute())adminLog($conexao,$acao,'curso',$acao==='criar'?$conexao->insert_id:$id);$s->close();}}header('Location: cursos.php');exit;}
adminHeader('Gerenciar cursos');echo '<h2>Novo curso</h2><form method="post">';csrf_campo();echo '<input type="hidden" name="acao" value="criar"><label>Título <input name="titulo" maxlength="180" required></label><label>Descrição <textarea name="descricao"></textarea></label><label>Plataforma <input name="plataforma"></label><label>Carga horária <input type="number" name="carga_horaria" min="0"></label><label>Link <input type="url" name="link"></label><label>Categoria <input name="categoria"></label><button>Adicionar curso</button></form>';
$r=$conexao->query('SELECT id,titulo,descricao,plataforma,carga_horaria,link,categoria FROM cursos ORDER BY id DESC');echo '<h2>Cursos cadastrados</h2><div style="overflow:auto"><table><thead><tr><th>Título</th><th>Plataforma</th><th>Carga horária</th><th>Ação</th></tr></thead><tbody>';while($c=$r->fetch_assoc()){echo '<tr><td>'.e($c['titulo']).'</td><td>'.e($c['plataforma']).'</td><td>'.(int)$c['carga_horaria'].'</td><td><form method="post" onsubmit="return confirm(\'Excluir curso?\')">';csrf_campo();echo '<input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="'.(int)$c['id'].'"><button>Excluir</button></form><details><summary>Editar</summary><form method="post">';csrf_campo();echo '<input type="hidden" name="acao" value="editar"><input type="hidden" name="id" value="'.(int)$c['id'].'"><label>Título <input name="titulo" maxlength="180" required value="'.e($c['titulo']).'"></label><label>Descrição <textarea name="descricao">'.e($c['descricao']).'</textarea></label><label>Plataforma <input name="plataforma" value="'.e($c['plataforma']).'"></label><label>Carga horária <input type="number" name="carga_horaria" min="0" value="'.(int)$c['carga_horaria'].'"></label><label>Link <input type="url" name="link" value="'.e($c['link']).'"></label><label>Categoria <input name="categoria" value="'.e($c['categoria']).'"></label><button>Salvar</button></form></details></td></tr>'; }echo '</tbody></table></div>';adminFooter();
